import pandas as pd
df = pd.read_csv('${item}')
issues = []
missing = df.isnull().sum()
for col, count in missing.items():
    if count > 0:
        issues.append(f'{col}: {count} missing values')
dupes = df.duplicated().sum()
if dupes > 0:
    issues.append(f'{dupes} duplicate rows')
for col in df.select_dtypes(include='number').columns:
    q1 = df[col].quantile(0.25)
    q3 = df[col].quantile(0.75)
    iqr = q3 - q1
    outliers = ((df[col] < q1 - 1.5*iqr) | (df[col] > q3 + 1.5*iqr)).sum()
    if outliers > 0:
        issues.append(f'{col}: {outliers} outliers')
env['issues_report'] = {'file': '${item}', 'issues': issues, 'row_count': len(df), 'columns': list(df.columns)}

import pandas as pd
df = pd.read_csv('${item}')
repairs = []
before = len(df)
df = df.drop_duplicates()
if len(df) < before:
    repairs.append(f'Removed {before - len(df)} duplicate rows')
for col in df.select_dtypes(include='number').columns:
    if df[col].isnull().any():
        median = df[col].median()
        count = df[col].isnull().sum()
        df[col] = df[col].fillna(median)
        repairs.append(f'Filled {count} missing in {col} with median {median}')
for col in df.select_dtypes(include='object').columns:
    if df[col].isnull().any():
        mode = df[col].mode()[0]
        count = df[col].isnull().sum()
        df[col] = df[col].fillna(mode)
        repairs.append(f'Filled {count} missing in {col} with mode {mode}')
