file_path = "${item}"
schema = ${schema_report}

with open(file_path, 'r') as f:
    reader = csv.DictReader(f)
    rows = list(reader)
    columns = reader.fieldnames or []

expected_types = {}
for col in schema.get('columns', []):
    expected_types[col['name']] = col['typeName']

type_errors = []
missing_values = []
duplicates = []
outliers = []
schema_drift = []

for col in columns:
    if col not in expected_types:
        schema_drift.append(f"Unexpected column: {col}")

for i, row in enumerate(rows):
    for col in columns:
        val = row.get(col, '')
        if val is None or str(val).strip() == '':
            missing_values.append(f"Row {i+1}, column '{col}': missing value")

seen = set()
for i, row in enumerate(rows):
    row_tuple = tuple(row.values())
    if row_tuple in seen:
        duplicates.append(f"Row {i+1}: duplicate of earlier row")
    seen.add(row_tuple)

for col in columns:
    col_type = expected_types.get(col, 'String')
    numeric_values = []
    for i, row in enumerate(rows):
        val = row.get(col, '')
        if val is None or str(val).strip() == '':
            continue
        if col_type in ('Number', 'Integer'):
            try:
                numeric_values.append(float(val))
            except (ValueError, TypeError):
                type_errors.append(f"Row {i+1}, column '{col}': expected {col_type}, got '{val}'")
    if len(numeric_values) > 4:
        sorted_vals = sorted(numeric_values)
        q1 = sorted_vals[len(sorted_vals) // 4]
        q3 = sorted_vals[3 * len(sorted_vals) // 4]
        iqr = q3 - q1
        lower = q1 - 1.5 * iqr
        upper = q3 + 1.5 * iqr
        for i, row in enumerate(rows):
            val = row.get(col, '')
            if val is None or str(val).strip() == '':
                continue
            try:
                num = float(val)
                if num < lower or num > upper:
                    outliers.append(f"Row {i+1}, column '{col}': value {num} outside [{lower:.2f}, {upper:.2f}]")
            except (ValueError, TypeError):
                pass

env['issue_report'] = {
    'file': file_path,
    'type_errors': type_errors,
    'missing_values': missing_values,
    'duplicates': duplicates,
